def.body:
Log.info do "Scaleway API: Updating #{record_type} record for #{domain}" end

body_string = {
  changes: [{
    set: {
      id: record[:id].to_s,
      records: [{
        data: ip,
        name: record[:name].to_s,
        ttl: record[:ttl],
        type: record_type,
      }],
    },
  }],
}.to_json

parse_response(execute_request("PATCH", "/domain/v2beta1/dns-zones/#{domain}/records", body_string))
